-- Friendship KeyChain: 20 dummy band-themed orders
-- All customer names, phone numbers and Instagram handles below are fictional.
-- Artwork sources are CC0 ClipSafari images. See source links at the bottom.
-- Safe to re-run: removes ONLY rows created by this demo script (notes marker).

DELETE FROM public.orders
WHERE notes LIKE '[DUMMY DATA - BAND TEST]%';


-- Verify the 20 demo rows:
SELECT customer_name, product_name, quantity, status, created_at
FROM public.orders
WHERE notes LIKE '[DUMMY DATA - BAND TEST]%'
ORDER BY created_at DESC;

